    "count": 125,
    "policy": {
      "policy_id": "horizon-stratification-v2",
      "policy_version": "2.0.0",
      "horizons": [
        {
          "days": 0,
          "label": "T+0",
          "name": "Same-day / walk-up",
          "description": "Purchased on the day of departure.",
          "advance_purchase_category": "last_minute",
          "statistical_rationale": "Captures urgent and distressed travel demand. Price level here reflects willingness to pay under time constraint, which is a different consumer decision from planned travel and must not be pooled with it."
        },
        {
          "days": 3,
          "label": "T+3",
          "name": "Short notice",
          "description": "Three days before departure.",
          "advance_purchase_category": "short_notice",
          "statistical_rationale": "Brackets the short-notice business travel boundary used by airline revenue management systems."
        },
        {
          "days": 7,
          "label": "T+7",
          "name": "One week advance",
          "description": "Seven days before departure.",
          "advance_purchase_category": "advance_7",
          "statistical_rationale": "A common revenue-management threshold at which discount fare buckets close."
        },
        {
          "days": 15,
          "label": "T+15",
          "name": "Two week advance",
          "description": "Fifteen days before departure.",
          "advance_purchase_category": "advance_14",
          "statistical_rationale": "Covers the 14/21-day advance purchase fare classes typical of planned business and early leisure travel."
        },
        {
          "days": 30,
          "label": "T+30",
          "name": "One month advance",
          "description": "Thirty days before departure.",
          "advance_purchase_category": "advance_30",
          "statistical_rationale": "Planned discretionary leisure travel. Serves as the reference anchor for the advance-purchase curve."
        }
      ],
      "weighting": {
        "method": "equal",
        "status": "PROVISIONAL",
        "formula": "alpha_h = 1 / H for each of the H horizons that has a computable index",
        "weights": {
          "T+0": 0.2,
          "T+3": 0.2,
          "T+7": 0.2,
          "T+15": 0.2,
          "T+30": 0.2
        },
        "is_official_cpi_weight": false,
        "why": [
          "Ideally alpha_h would be the share of tickets actually SOLD at each advance-purchase",
          "horizon. That distribution is held by airlines and is not published, so it cannot be",
          "estimated from observable fare quotes.",
          "Equal weighting is therefore chosen as an explicit, documented, and defensible",
          "convention rather than an estimate. Its key property is that it is FIXED: because the",
          "weights do not depend on how many observations each horizon happens to contribute,",
          "the combined route index cannot move merely because the sample composition shifted.",
          "Pooling observations across horizons (the previous behaviour) does not have this",
          "property: it makes the index sensitive to the horizon mix, because T+0 fares sit at a",
          "structurally higher level than T+30 fares."
        ],
        "renormalization_policy": "If a horizon has no computable index for a period, the remaining horizons are renormalized to sum to 1.0 and the missing horizon is recorded on the index record. The index is only published when at least min_horizons_for_route_index horizons are present.",
        "upgrade_path": "Replace with booking-distribution weights if and when advance-purchase sales shares become available from a citable source. Any such change is a methodology change and must create an index_revisions record."
      },
      "requirements": {
        "min_horizons_for_route_index": 2,
        "min_matched_products_per_horizon": 3
      }
    },
