    "methodology": {
      "method": "passenger_volume",
      "status": "PROVISIONAL",
      "formula": "w_r = pax_r / sum_k(pax_k)",
      "label": "Provisional passenger-volume weights (not official CPI expenditure shares)",
      "is_official_cpi_expenditure_weight": false,
      "rationale": [
        "A production CPI component requires EXPENDITURE shares: passengers x average fare.",
        "Route-level expenditure data for Indian domestic aviation is not publicly available",
        "at the city-pair granularity this basket needs, so passenger volume is used as a",
        "documented proxy.",
        "This is a methodological simplification, not an official MoSPI weighting scheme, and",
        "every API response that exposes weights reports status=PROVISIONAL alongside them."
      ],
      "upgrade_path": "Multiply pax_r by the route's mean observed fare to obtain an expenditure proxy once a stable fare series exists for every route in the basket.",
      "source_note": "Monthly passenger volumes are approximations of published DGCA domestic city-pair traffic, rounded to the nearest 10,000. They are illustrative magnitudes for a prototype basket, not a verbatim reproduction of a DGCA table.",
      "review_policy": "Weights are held fixed within an index reference period and re-derived only when this file's basket_version changes. Any change creates an index_revisions record."
    },
